const runnerBase = process.env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = process.env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const response = $input.first().json;
const items = Array.isArray(response.results) ? response.results : [];
const childrenByParent = new Map();
for (const item of items) {
  if (!item.parent) continue;
  const bucket = childrenByParent.get(item.parent) || [];
  bucket.push(item.id);
  childrenByParent.set(item.parent, bucket);
}

const candidates = items.filter((item) => {
  const html = String(item.description_html || '');
  return !item.completed_at && !item.parent && html.includes('Task Breakdown Requested') && !childrenByParent.has(item.id);
});

const created = [];
for (const item of candidates) {
  const html = String(item.description_html || '');
  const rawCriteria = Array.from(html.matchAll(/<li>(.*?)<\/li>/g)).map((match) => match[1].replace(/<[^>]+>/g, '').trim()).filter(Boolean).slice(0, 4);
  const criteria = rawCriteria.length > 0 ? rawCriteria : ['Review and refine scope', 'Implement the main path', 'Validate and document outcomes'];
  for (let index = 0; index < criteria.length; index += 1) {
    const criterion = criteria[index];
    const payload = {
      name: `${item.name} / Subtask ${index + 1}`,
      description_html: `<p>${criterion}</p><h3>Repo Metadata</h3><ul><li><strong>Generated By:</strong> <code>Plane Task Decomposer Writeback</code></li></ul>`,
      parent: item.id,
      priority: 'medium',
    };
    const createResponse = await fetch(`${process.env.PLANE_API_BASE_URL}/api/v1/workspaces/${process.env.PLANE_WORKSPACE_SLUG}/projects/${process.env.PLANE_PROJECT_ID}/work-items/`, {
      method: 'POST',
      headers: {
        'X-API-Key': process.env.PLANE_API_KEY,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(payload),
    });
    created.push({ parentId: item.id, criterion, ok: createResponse.ok, status: createResponse.status });
  }
}

const reportRelativePath = `task-decomposer/${new Date().toISOString().replace(/[:]/g, '-')}.md`;
const reportContent = [
  '# Plane Task Decomposer Writeback',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Candidates: ${candidates.length}`,
  `Subtasks attempted: ${created.length}`,
  '',
  '## Results',
  '',
  created.length > 0 ? '```json\n' + JSON.stringify(created, null, 2) + '\n```' : 'No eligible tasks found.',
].join('\n');
const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: reportContent }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);

return [{ json: { candidates: candidates.length, createdCount: created.length, reportRelativePath } }];
